import{_ as i,o as e,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const h=JSON.parse('{"title":"Anti-Monopoly Law","description":"","frontmatter":{},"headers":[],"relativePath":"en/47-反垄断法.md","filePath":"en/47-反垄断法.md"}'),a={name:"en/47-反垄断法.md"};function r(s,t,l,c,d,p){return e(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="anti-monopoly-law" tabindex="-1">Anti-Monopoly Law <a class="header-anchor" href="#anti-monopoly-law" aria-label="Permalink to &quot;Anti-Monopoly Law&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document No.</td><td>47</td></tr><tr><td>Module</td><td>Legal System and Governance Framework</td></tr><tr><td>Core Keywords</td><td>Anti-monopoly, Fair competition, Symbiotic market order, Prohibition of predatory behavior, Maintenance of the joint advancement of all races</td></tr></tbody></table><h2 id="i-legislative-purpose-and-basic-principles" tabindex="-1">I. Legislative Purpose and Basic Principles <a class="header-anchor" href="#i-legislative-purpose-and-basic-principles" aria-label="Permalink to &quot;I. Legislative Purpose and Basic Principles&quot;">​</a></h2><p>The <em>Anti-Monopoly Law</em> is one of the five supporting laws of the Anchor Symbiotic Civilization. It aims to prevent monopoly and predatory behavior in cultivation resources, cultivation sects, commercial markets, and other domains, maintain fair competition and the symbiotic market order of the Hengyuan Universe, and ensure the &quot;joint advancement of all races&quot; by ensuring that no power or organization can seize development opportunities through monopoly.</p><p>This Law establishes the following basic principles:</p><table tabindex="0"><thead><tr><th>Principle</th><th>Connotation</th></tr></thead><tbody><tr><td>Fair Competition</td><td>All subjects compete on an equal basis; prohibits the abuse of market dominance and unfair competition</td></tr><tr><td>Open Market</td><td>Prohibits monopoly agreements, market division, and restricted competition that exclude or restrict competition</td></tr><tr><td>Protection of the Weak</td><td>Tilted protection for new cultivators, junior races, and small and medium-sized organizations</td></tr><tr><td>Symbiotic Order</td><td>The market must serve the joint advancement of all races; prohibits the plundering of public interests by capital and power</td></tr><tr><td>Unified Enforcement</td><td>Anti-monopoly enforcement is carried out by a unified institution; prohibits local protectionism and monopolistic behavior across planes</td></tr></tbody></table><h2 id="ii-definition-of-monopoly" tabindex="-1">II. Definition of Monopoly <a class="header-anchor" href="#ii-definition-of-monopoly" aria-label="Permalink to &quot;II. Definition of Monopoly&quot;">​</a></h2><p>This Law defines the following acts as monopolistic acts, which are prohibited:</p><ol><li><strong>Monopoly Agreements</strong>: Agreements between competitors or between upstream and downstream businesses that fix prices, divide markets, restrict output, boycott, etc.</li><li><strong>Abuse of Market Dominance</strong>: The abuse of a dominant market position to sell at unfair high prices, sell below cost, impose unreasonable trading conditions, refuse to trade, tie-in sales, etc.</li><li><strong>Concentration of Operators</strong>: Mergers, acquisitions, and joint ventures that eliminate or restrict competition, with prior declaration to the anti-monopoly authority for review.</li><li><strong>Administrative Monopoly</strong>: The abuse of administrative power by state organs and public organizations to restrict competition, local protectionism, and industry monopoly.</li><li><strong>Cultivation Resource Monopoly</strong>: The monopoly control of cultivation resources, spiritual energy nodes, and secret realms, excluding others from cultivation.</li><li><strong>Talent Monopoly</strong>: The use of unfair means to exclusively control cultivation talents, restricting the free flow of talents.</li></ol><h2 id="iii-anti-monopoly-institutions" tabindex="-1">III. Anti-Monopoly Institutions <a class="header-anchor" href="#iii-anti-monopoly-institutions" aria-label="Permalink to &quot;III. Anti-Monopoly Institutions&quot;">​</a></h2><p>The Symbiotic Court and its affiliated anti-monopoly enforcement institutions exercise the following functions:</p><table tabindex="0"><thead><tr><th>Institution</th><th>Function</th></tr></thead><tbody><tr><td>Anti-Monopoly Enforcement Bureau</td><td>Investigates monopoly acts, initiates investigations into suspected monopolistic acts</td></tr><tr><td>Monopoly Review Committee</td><td>Reviews concentration of operators and market structure changes</td></tr><tr><td>Price Supervision Office</td><td>Supervises the price behavior of important cultivation resources and commodities</td></tr><tr><td>Cross-Plane Coordination Office</td><td>Coordinates anti-monopoly enforcement across planes, preventing cross-plane monopolies</td></tr></tbody></table><p>The anti-monopoly enforcement institution enjoys investigative powers: it may require relevant parties to explain situations, inspect books and records, seal and detain evidence, etc. Investigated parties shall cooperate and shall not refuse or obstruct.</p><h2 id="iv-special-provisions-on-cultivation-resource-monopoly" tabindex="-1">IV. Special Provisions on Cultivation Resource Monopoly <a class="header-anchor" href="#iv-special-provisions-on-cultivation-resource-monopoly" aria-label="Permalink to &quot;IV. Special Provisions on Cultivation Resource Monopoly&quot;">​</a></h2><p>Cultivation resources are public wealth of the Hengyuan Universe, and this Law establishes special provisions on their monopoly prevention:</p><ol><li><strong>Resource Access Equality</strong>: All races and cultivators have equal rights to access cultivation resources; no sect or organization may exclusively occupy core resources.</li><li><strong>Spiritual Energy Node Sharing</strong>: Key spiritual energy nodes implement a sharing management system; exclusive occupation and the establishment of private cultivation enclaves are prohibited.</li><li><strong>Secret Realm Open System</strong>: Secret realms discovered by any subject shall be reported to the management institution and enter the public resource system; secret occupation is prohibited.</li><li><strong>Dan Pill Market Regulation</strong>: Important dan pills and spiritual medicines implement price guidance and supply supervision; hoarding and price gouging are prohibited.</li><li><strong>Artifact Circulation Supervision</strong>: The circulation of high-level artifacts shall be registered and managed; the establishment of an armed artifact monopoly through control of artifact sources is prohibited.</li></ol><h2 id="v-remedies-and-legal-liability" tabindex="-1">V. Remedies and Legal Liability <a class="header-anchor" href="#v-remedies-and-legal-liability" aria-label="Permalink to &quot;V. Remedies and Legal Liability&quot;">​</a></h2><p>For monopolistic acts, this Law provides the following remedies and liabilities:</p><ul><li><strong>Order to Stop</strong>: The anti-monopoly enforcement institution orders the cessation of monopolistic acts.</li><li><strong>Fines</strong>: Fines are imposed according to the illegal gains and the severity of the circumstances.</li><li><strong>Disgorgement of Illegal Gains</strong>: Illegal gains obtained through monopolistic acts are confiscated.</li><li><strong>Revocation of Qualifications</strong>: In serious circumstances, business licenses or cultivation sect qualifications are revoked.</li><li><strong>Compensation for Damages</strong>: Victims of monopolistic acts have the right to claim compensation for damages.</li><li><strong>Criminal Liability</strong>: If a monopolistic act constitutes a crime, criminal liability is pursued.</li></ul><h2 id="vi-public-interest-litigation" tabindex="-1">VI. Public Interest Litigation <a class="header-anchor" href="#vi-public-interest-litigation" aria-label="Permalink to &quot;VI. Public Interest Litigation&quot;">​</a></h2><p>For monopolistic acts that harm public interests, the following subjects may file anti-monopoly public interest litigation with the Symbiotic Court:</p><ul><li>Anti-monopoly enforcement institutions</li><li>Symbiotic public welfare organizations</li><li>Other legally prescribed subjects</li></ul><p>Public interest litigation aims to stop monopolistic acts, protect the public interest of the market order, and compensate for damages to the public interest.</p><h2 id="vii-application-of-the-law" tabindex="-1">VII. Application of the Law <a class="header-anchor" href="#vii-application-of-the-law" aria-label="Permalink to &quot;VII. Application of the Law&quot;">​</a></h2><p>This Law applies to all monopolistic acts occurring within the Hengyuan Universe, including monopolistic acts by subjects from other universes within the jurisdiction of the Hengyuan Universe. For monopolistic acts occurring across universes, the principle of reciprocity and consultation shall apply.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The <em>Anti-Monopoly Law</em> is the legal bulwark of the &quot;joint advancement of all races&quot; philosophy of the Anchor Symbiotic Civilization. By defining and punishing monopolistic acts, establishing dedicated institutions, and regulating the monopoly of cultivation resources, it ensures the fairness and openness of the symbiotic market, prevents the plundering of resources and development opportunities by any power, and provides institutional guarantees for the joint advancement of all races.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Symbiotic Constitution: General Principles)</li><li>42-消费者保护法 (Consumer Protection Law)</li><li>41-共生劳动法 (Symbiotic Labor Law)</li><li>07-联产承包机制详解 (Detailed Explanation of the Joint-Output Contracting Mechanism)</li></ul>',29)])])}const m=i(a,[["render",r]]);export{h as __pageData,m as default};
